package com.footballacademy.model;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="video_assets", indexes={@Index(name="idx_video_match", columnList="match_id"),@Index(name="idx_video_player", columnList="player_id")})
public class VideoAsset { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="match_id") @JsonIgnore private Match match; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="player_id") @JsonIgnore private Player player; @Column(length=1000) private String videoUrl; private Long durationSeconds; private String resolution; private LocalDateTime uploadedAt=LocalDateTime.now(); @OneToOne(mappedBy="videoAsset", cascade=CascadeType.ALL, orphanRemoval=true) private VideoAnalysis analysis; public boolean isValid(){return videoUrl!=null&&!videoUrl.isBlank()&&durationSeconds!=null&&durationSeconds>0;} public Long getId(){return id;} public void setId(Long id){this.id=id;} public Match getMatch(){return match;} public void setMatch(Match match){this.match=match;} public Player getPlayer(){return player;} public void setPlayer(Player player){this.player=player;} public String getVideoUrl(){return videoUrl;} public void setVideoUrl(String videoUrl){this.videoUrl=videoUrl;} public Long getDurationSeconds(){return durationSeconds;} public void setDurationSeconds(Long durationSeconds){this.durationSeconds=durationSeconds;} public String getResolution(){return resolution;} public void setResolution(String resolution){this.resolution=resolution;} public LocalDateTime getUploadedAt(){return uploadedAt;} public void setUploadedAt(LocalDateTime uploadedAt){this.uploadedAt=uploadedAt;} public VideoAnalysis getAnalysis(){return analysis;} public void setAnalysis(VideoAnalysis analysis){this.analysis=analysis;} }
